	@Test
	void directSinkReacquiresProducerWhenAnOlderParticipantCompletesAfterItsAdmission(@TempDir File directory)
			throws Exception {
		ObservedStore store = new ObservedStore(directory,
				configuration(true).setAsyncValueCleanupMaxPendingProducers(2));
		store.init();
		CountDownLatch resumed = new CountDownLatch(1);
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			add(store);
			AsyncValueRetirementCoordinator coordinator = store.getBackingStore().asyncValueCleanupCoordinator();
			SailSource source = store.getBackingStore().getExplicitSailSource();
			CountDownLatch reusedAdmission = new CountDownLatch(1);
			AtomicReference<Thread> nextWriter = new AtomicReference<>();
			AtomicReference<Object> sharedOwner = new AtomicReference<>();
			AtomicBoolean pauseOnce = new AtomicBoolean(true);
			IRI followingSubject = VF.createIRI("urn:async-cleanup:following-direct-owner");
			store.afterCleanupAdmission = owner -> {
				if (Thread.currentThread() == nextWriter.get()) {
					assertSame(sharedOwner.get(), owner, "both direct sinks must share the source's writer owner");
					if (pauseOnce.compareAndSet(true, false)) {
						reusedAdmission.countDown();
						await(resumed);
					}
				} else {
					sharedOwner.compareAndSet(null, owner);
				}
			};
			try (PausedWorker paused = new PausedWorker(coordinator);
					var executor = Executors.newSingleThreadExecutor()) {
				SailSink preceding = source.sink(IsolationLevels.READ_COMMITTED);
				try {
					preceding.deprecate(VF.createStatement(SUBJECT, PREDICATE, OBJECT));
					var following = executor.submit(() -> {
						nextWriter.set(Thread.currentThread());
						try (SailSink sink = source.sink(IsolationLevels.READ_COMMITTED)) {
							sink.approve(followingSubject, PREDICATE, OBJECT, null);
							sink.flush();
						}
					});
					assertTrue(reusedAdmission.await(10, TimeUnit.SECONDS));
					preceding.flush();
					preceding.close();
					paused.awaitEntered();
					// The following sink passed admission while the preceding producer existed. That producer has
					// now moved to the worker, so acquiring native authority must validate and renew its admission.
					resumed.countDown();
					following.get(10, TimeUnit.SECONDS);
				} finally {
					resumed.countDown();
					store.afterCleanupAdmission = owner -> {
					};
					preceding.close();
				}
			}
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			assertEquals(0, coordinator.metrics().activeProducers());
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(SUBJECT));
			try (SailConnection reader = store.getConnection()) {
				assertFalse(reader.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
				assertTrue(reader.hasStatement(followingSubject, PREDICATE, OBJECT, false));
			}
		} finally {
			resumed.countDown();
			store.afterCleanupAdmission = owner -> {
			};
			store.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void directPublicationKeepsCandidatesUntilItsFinalOwnerReleases(boolean explicitOwner, @TempDir File directory)
			throws Exception {
		ObservedStore store = new ObservedStore(directory, configuration(true));
		store.init();
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			add(store);
			AsyncValueRetirementCoordinator coordinator = store.getBackingStore().asyncValueCleanupCoordinator();
			try (PausedWorker paused = new PausedWorker(coordinator)) {
				SailSource source = store.getBackingStore().getExplicitSailSource();
				try (SailClosable publication = explicitOwner ? source.beginPublication(new Object())
						: source.beginPublication()) {
					try (SailClosable prepared = source.beginPreparedWrite();
							SailSink sink = source.sink(IsolationLevels.READ_COMMITTED)) {
						sink.deprecate(VF.createStatement(SUBJECT, PREDICATE, OBJECT));
						sink.flush();
					}
					// Closing the prepared participant cannot discard candidates while the outer publication owns them.
				}
				paused.awaitEntered();
				try (SailConnection reader = store.getConnection()) {
					assertFalse(reader.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
				}
			}
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(SUBJECT));
			assertEquals(0, coordinator.metrics().activeProducers(),
					"a completed direct owner must not leak admission");
		} finally {
			store.shutDown();
		}
	}

	@Test
	void temporaryOverflowModelsDoNotExhaustCleanupCapacityOrStartAWorker(@TempDir File directory) throws Exception {
		LmdbStoreConfig config = configuration(true).setAsyncValueCleanupMaxCandidates(16)
				.setAsyncValueCleanupMaxBytes(4096)
				.setAsyncValueCleanupBatchSize(1)
				.setAsyncValueCleanupMaxPendingProducers(1);
		ObservedStore store = new ObservedStore(directory, config);
		store.init();
		AtomicReference<File> overflowDirectory = new AtomicReference<>();
		AtomicReference<LmdbSailStore> overflowStore = new AtomicReference<>();
		try {
			class OverflowOwner extends MemoryOverflowModel {
				@Override
				protected LmdbSailStore createSailStore(File temporaryDirectory) throws IOException {
					overflowDirectory.set(temporaryDirectory);
					LmdbSailStore overflow = store.createOverflowStore(temporaryDirectory, false);
					overflowStore.set(overflow);
					return overflow;
				}

				SailSourceModel createDiskModel() {
					overflowToDiskInner(new LinkedHashModel());
					return disk;
				}
			}
			try (OverflowOwner owner = new OverflowOwner()) {
				// Exercise the native overflow model and its resource owner without a GC-pressure trigger.
				SailSourceModel model = owner.createDiskModel();
				for (int i = 0; i < 8; i++) {
					IRI subject = VF.createIRI("urn:async-cleanup:overflow:" + i);
					assertTrue(model.add(subject, PREDICATE, OBJECT));
					assertTrue(model.contains(subject, PREDICATE, OBJECT));
					assertTrue(model.remove(subject, PREDICATE, OBJECT));
					assertFalse(model.contains(subject, PREDICATE, OBJECT));
				}
				assertFalse(model.contains(null, null, null), "the native overflow dataset must be empty");
				assertNull(overflowStore.get().asyncValueCleanupCoordinator(),
						"disposable transaction-delta stores release their whole directory instead of queueing IDs");
			}
			assertFalse(overflowDirectory.get().exists(), "model close must dispose the entire temporary store");
			assertEquals(0, store.getBackingStore().asyncValueCleanupCoordinator().metrics().activeProducers());
		} finally {
			store.shutDown();
		}
	}

