	@Test
	void rejectedShutdownInsideStatementListenerLeavesStoreWritable(@TempDir File directory) throws Exception {
		ObservedStore store = new ObservedStore(directory, configuration(true));
		store.init();
		try {
			LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			AtomicBoolean attempted = new AtomicBoolean();
			try (NotifyingSailConnection writer = store.getConnection()) {
				writer.addConnectionListener(new SailConnectionListener() {
					@Override
					public void statementAdded(Statement statement) {
						if (attempted.compareAndSet(false, true)) {
							SailException failure = assertThrows(SailException.class, store::shutDown);
							assertEquals("An active Sail operation cannot shut down its own store",
									failure.getMessage());
						}
					}

					@Override
					public void statementRemoved(Statement statement) {
					}
				});
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(SUBJECT, PREDICATE, OBJECT);
				assertTrue(attempted.get(), "the rejected shutdown must occur inside the admitted write");
				writer.commit();
			}
			assertTrue(store.initializedForTest());
			// A rejected reentrant shutdown must leave admission and maintenance usable for later transactions.
			remove(store);
			assertTrue(store.getBackingStore().asyncValueCleanupCoordinator().awaitEmpty(10, TimeUnit.SECONDS));
			add(store);
			try (SailConnection reader = store.getConnection()) {
				assertTrue(reader.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
			}
		} finally {
			store.shutDown();
		}
	}

