	@Test
	void commitAndPostCommitMaintenanceDoNotReclaimOnApplicationThread(@TempDir File directory) throws Exception {
		ObservedStore store = new ObservedStore(directory, configuration(true));
		store.init();
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			add(store);
			long originalId = values.getId(SUBJECT);
			AsyncValueRetirementCoordinator coordinator = store.getBackingStore().asyncValueCleanupCoordinator();
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			int before = store.maintenanceAttempts.get();
			int foregroundGcBefore = store.foregroundGcCalls.get();
			int foregroundReclamationBefore = store.foregroundReclamationCalls.get();
			try (PausedWorker paused = new PausedWorker(coordinator)) {
				remove(store);
				paused.awaitEntered();
				store.getBackingStore().completePostCommitValueMaintenance();
				assertEquals(before, store.maintenanceAttempts.get(),
						"both foreground reclamation entry points are off");
				assertEquals(foregroundGcBefore, store.foregroundGcCalls.get());
				assertEquals(foregroundReclamationBefore, store.foregroundReclamationCalls.get());
				assertFalse(values.hasRetiredIds(), "ordinary async commits do not write durable retirement indexes");
				assertFalse(contains(store));
				assertNotEquals(LmdbValue.UNKNOWN_ID, values.getId(SUBJECT), "the paused worker has not reclaimed it");
			}
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			assertTrue(store.maintenanceAttempts.get() > before);
			assertEquals("LmdbValueCleanup", store.maintenanceThread.get().getName());
			assertEquals(foregroundGcBefore, store.foregroundGcCalls.get());
			assertEquals(foregroundReclamationBefore, store.foregroundReclamationCalls.get());
			assertReclaimedOrDurablyRetired(store, values, originalId);
		} finally {
			store.shutDown();
		}
	}

	@Test
	void preparedRollbackDiscardsEveryCandidate(@TempDir File directory) throws Exception {
		ObservedStore store = new ObservedStore(directory, configuration(true));
		store.init();
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			add(store);
			long originalId = values.getId(SUBJECT);
			AsyncValueRetirementCoordinator coordinator = store.getBackingStore().asyncValueCleanupCoordinator();
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			long acknowledged = coordinator.metrics().acknowledgedCandidates();
			try (SailConnection writer = store.getConnection()) {
				// NONE deliberately publishes checkpoints during flush/prepare. Use an atomic snapshot transaction
				// here so prepare has not already made the deletion authoritative before rollback.
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.removeStatements(SUBJECT, PREDICATE, OBJECT);
				writer.prepare();
				writer.rollback();
			}
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			assertEquals(acknowledged, coordinator.metrics().acknowledgedCandidates());
			assertFalse(values.hasRetiredIds());
			assertTrue(contains(store));
			assertEquals(originalId, values.getId(SUBJECT));
		} finally {
			store.shutDown();
		}
	}

	@Test
	void noneRollbackRetainsCleanupForAnAlreadyPublishedPrefix(@TempDir File directory) throws Exception {
		ObservedStore store = new ObservedStore(directory, configuration(true));
		store.init();
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			add(store);
			AsyncValueRetirementCoordinator coordinator = store.getBackingStore().asyncValueCleanupCoordinator();
			long beforePublication = store.getBackingStore().dataRevision();
			try (PausedWorker paused = new PausedWorker(coordinator)) {
				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.NONE);
					writer.removeStatements(SUBJECT, PREDICATE, OBJECT);
					writer.flush();
					assertTrue(store.getBackingStore().dataRevision() > beforePublication,
							"NONE flush has already published the deletion checkpoint");
					writer.rollback();
				}
				paused.awaitEntered();
				assertFalse(contains(store), "rollback must preserve NONE's already committed prefix");
				assertNotEquals(LmdbValue.UNKNOWN_ID, values.getId(SUBJECT));
			}
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(SUBJECT));
		} finally {
			store.shutDown();
		}
	}

