	@Test
	void readerBetweenReintroductionAndRemovalPinsTheOldCandidate(@TempDir File directory) throws Exception {
		ObservedStore store = new ObservedStore(directory, configuration(true));
		store.init();
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			add(store);
			long originalId = values.getId(SUBJECT);
			AsyncValueRetirementCoordinator coordinator = store.getBackingStore().asyncValueCleanupCoordinator();
			try (PausedWorker paused = new PausedWorker(coordinator)) {
				remove(store);
				paused.awaitEntered();
				add(store);
				try (SailDataset pinned = pin(store)) {
					remove(store);
					paused.release();
					paused.awaitRetry();
					assertPinnedStatement(pinned);
					assertEquals(originalId, values.getId(SUBJECT));
					assertTrue(coordinator.metrics().activeProducers() > 0,
							"reader-pinned work remains reserved until it is safe to collect");
				}
			}
			coordinator.signal();
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			assertReclaimedOrDurablyRetired(store, values, originalId);
		} finally {
			store.shutDown();
		}
	}

