	@Test
	void waitingProducerCannotAcquireANewSnapshotFromItsOwnConnection(@TempDir File directory) throws Exception {
		// Keep admission pending throughout the deliberate one-second snapshot-exclusion observation.
		LmdbStoreConfig config = configuration(true).setAsyncValueCleanupMaxPendingProducers(1)
				.setAsyncValueCleanupAdmissionTimeoutMillis(10_000);
		AtomicBoolean observeRead = new AtomicBoolean();
		CountDownLatch readAcquisitionStarted = new CountDownLatch(1);
		CountDownLatch nativeReadAcquired = new CountDownLatch(1);
		CountDownLatch releaseRead = new CountDownLatch(1);
		ObservedStore store = new ObservedStore(directory, config) {
			@Override
			protected NotifyingSailConnection getConnectionInternal() throws SailException {
				return new LmdbStoreConnection(this) {
					@Override
					protected SailClosable beginDatasetAcquisition(IsolationLevel level) throws SailException {
						if (observeRead.get()) {
							readAcquisitionStarted.countDown();
						}
						SailClosable acquisition = super.beginDatasetAcquisition(level);
						if (observeRead.get()) {
							nativeReadAcquired.countDown();
						}
						return acquisition;
					}
				};
			}
		};
		store.init();
		try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
			LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			add(store);
			AsyncValueRetirementCoordinator coordinator = store.getBackingStore().asyncValueCleanupCoordinator();
			CountDownLatch admissionWait = new CountDownLatch(1);
			coordinator.admissionWaitStartedForTest(admissionWait::countDown);
			try (SailConnection connection = store.getConnection();
					PausedWorker paused = new PausedWorker(coordinator)) {
				remove(store);
				paused.awaitEntered();
				connection.begin(IsolationLevels.SNAPSHOT);
				var writer = executor.submit(() -> connection.addStatement(SUBJECT, PREDICATE, OBJECT));
				assertTrue(admissionWait.await(10, TimeUnit.SECONDS));
				observeRead.set(true);
				var reader = executor.submit(() -> {
					try (var statements = connection.getStatements(null, null, null, false)) {
						statements.hasNext();
						await(releaseRead);
					}
				});
				try {
					assertTrue(readAcquisitionStarted.await(10, TimeUnit.SECONDS));
					// The read has reached acquisition. Its native snapshot must stay behind this connection's
					// already-waiting admission, otherwise the producer pins the very cleanup that can admit it.
					assertFalse(nativeReadAcquired.await(1, TimeUnit.SECONDS),
							"a connection waiting for cleanup capacity must not acquire a new native snapshot");
					assertEquals(Long.MAX_VALUE, store.getBackingStore()
							.getTripleStore()
							.getTxnManager()
							.minPinnedSnapshotRevision());
					paused.release();
					writer.get(10, TimeUnit.SECONDS);
					assertTrue(nativeReadAcquired.await(10, TimeUnit.SECONDS));
					releaseRead.countDown();
					reader.get(10, TimeUnit.SECONDS);
					connection.rollback();
				} finally {
					releaseRead.countDown();
					writer.cancel(true);
					reader.cancel(true);
					coordinator.admissionWaitStartedForTest(() -> {
					});
				}
			}
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			assertEquals(0, coordinator.metrics().activeProducers());
		} finally {
			releaseRead.countDown();
			store.shutDown();
		}
	}

