	@Test
	void failedMaintenanceCommitRetainsTheBatchUntilRetry(@TempDir File directory) throws Exception {
		ObservedStore store = new ObservedStore(directory, configuration(true));
		store.init();
		CountDownLatch retried = new CountDownLatch(1);
		CountDownLatch retryAllowed = new CountDownLatch(1);
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			add(store);
			long originalId = values.getId(SUBJECT);
			AsyncValueRetirementCoordinator coordinator = store.getBackingStore().asyncValueCleanupCoordinator();
			AtomicInteger attempts = new AtomicInteger();
			coordinator.beforeBatchForTest(() -> {
				if (attempts.incrementAndGet() == 2) {
					retried.countDown();
					await(retryAllowed);
				}
			});
			store.failNextMaintenance.set(true);
			remove(store);
			assertTrue(retried.await(10, TimeUnit.SECONDS));
			assertEquals(1, coordinator.metrics().failedBatches());
			assertEquals(0, coordinator.metrics().acknowledgedCandidates());
			assertEquals(originalId, values.getId(SUBJECT), "aborted maintenance leaves dictionary mappings intact");
			retryAllowed.countDown();
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			assertReclaimedOrDurablyRetired(store, values, originalId);
			assertFalse(contains(store));
		} finally {
			retryAllowed.countDown();
			store.shutDown();
		}
	}

