	@ParameterizedTest
	@EnumSource(value = IsolationLevels.class, names = { "NONE", "READ_COMMITTED" })
	void directSailSinkPublishesAndDiscardsCandidatesWithItsNativeTransaction(IsolationLevels isolation,
			@TempDir File directory) throws Exception {
		ObservedStore store = new ObservedStore(directory, configuration(true));
		store.init();
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			LmdbSailStore backing = store.getBackingStore();
			try (SailSink sink = backing.getExplicitSailSource().sink(isolation)) {
				sink.approve(SUBJECT, PREDICATE, OBJECT, null);
				sink.flush();
			}
			assertTrue(contains(store));
			long originalId = values.getId(SUBJECT);
			AsyncValueRetirementCoordinator coordinator = backing.asyncValueCleanupCoordinator();
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			long acknowledged = coordinator.metrics().acknowledgedCandidates();
			try (SailSink sink = backing.getExplicitSailSource().sink(isolation)) {
				sink.deprecate(VF.createStatement(SUBJECT, PREDICATE, OBJECT));
				sink.prepare();
				// Closing without flush abandons the direct sink's unpublished native transaction.
			}
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			assertEquals(acknowledged, coordinator.metrics().acknowledgedCandidates());
			assertTrue(contains(store));
			assertEquals(originalId, values.getId(SUBJECT));
			try (PausedWorker paused = new PausedWorker(coordinator)) {
				try (SailSink sink = backing.getExplicitSailSource().sink(isolation)) {
					sink.deprecate(VF.createStatement(SUBJECT, PREDICATE, OBJECT));
					sink.flush();
				}
				paused.awaitEntered();
				assertFalse(contains(store));
				assertEquals(originalId, values.getId(SUBJECT));
			}
			assertTrue(coordinator.awaitEmpty(10, TimeUnit.SECONDS));
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(SUBJECT));
		} finally {
			store.shutDown();
		}
	}

